from PIL import Image
im=Image.open('radiograph.jpg').convert('RGB')
w,h=im.size
regs={
 'mand_all':(0.22,0.50,0.80,0.80),
 'max_all':(0.22,0.30,0.80,0.50),
}
for k,(a,b,c,d) in regs.items():
    box=(int(w*a),int(h*b),int(w*c),int(h*d))
    cr=im.crop(box); cr=cr.resize((cr.width*2,cr.height*2)); cr.save(k+'.png'); print(k,box)
"", "description": "Crop mandible and maxilla rows"}

